questionvariables.text:
/* Design: two inequalities and the most profitable whole-number plan. Source: adapted from SMP Book 5 (Metric), Chapter 8, Exercise B, question 5. Vertex whole on 4 entries, a fraction on 6; the best plan lies within 2 of the vertex.
   trp: the vertex rounded to the nearest whole numbers (non-whole vertex), or one more of the first item (whole vertex): always outside R.
   tv2: profit at the vertex (non-whole) or at the far vertex on the x-axis (whole). */
/* lincan(q): canonical form of a linear inequality in x and y: [strict?, [a, b, c]] meaning a*x + b*y + c (< or <=) 0 */
lincan(q) := block([r, d, s], r: op(q), d: expand(lhs(q) - rhs(q)),
    if r = ">" or r = ">=" then d: -d,
    s: is(r = "<" or r = ">"),
    [s, map(lambda([t], float(t)), [coeff(d, x), coeff(d, y), subst([x = 0, y = 0], d)])]);
lpar(u, v) := is(abs(u[1]*v[2] - u[2]*v[1]) + abs(u[1]*v[3] - u[3]*v[1]) + abs(u[2]*v[3] - u[3]*v[2]) < 1/10^9 * (abs(u[1]) + abs(u[2]) + abs(u[3])) * (abs(v[1]) + abs(v[2]) + abs(v[3])));
ldot(u, v) := u[1]*v[1] + u[2]*v[2] + u[3]*v[3];
/* lcls(L, T): "same" region; "dir" same boundary, other side, same strictness; "strict" same side, other strictness; "both"; "other" */
lcls(L, T) := block([l: lincan(L), t: lincan(T)],
    if not lpar(l[2], t[2]) then "other"
    elseif ldot(l[2], t[2]) > 0 then (if l[1] = t[1] then "same" else "strict")
    elseif l[1] = t[1] then "dir" else "both");
/* the validator: an inequality in x and y, linear */
validate_ineq(ex) := block([e: ev(ex, simp), d],
    if atom(e) or not member(op(e), ["<", "<=", ">", ">="]) then
        "Type an inequality using <, <=, > or >=, for example 2*x+3*y<=60. An equation with = is not an inequality."
    elseif listofvars(e) = [] or not every(lambda([v], member(v, [x, y])), listofvars(e)) then "Use only the letters x and y."
    else (d: ev(expand(lhs(e) - rhs(e)), simp),
          if not ev(polynomialp(d, [x, y]), simp) then
              "This inequality should be linear: only numbers times x and y, added or subtracted."
          elseif ev(hipow(d, x), simp) > 1 or ev(hipow(d, y), simp) > 1 or not freeof(x, ev(coeff(d, y), simp)) then
              "This inequality should be linear: no powers or products of x and y." else ""));
/* mkineq([a, b, rel, c]): the inequality a*x + b*y rel c */
mkineq(L) := if L[3] = "<=" then L[1]*x + L[2]*y <= L[4] elseif L[3] = "<" then L[1]*x + L[2]*y < L[4]
    elseif L[3] = ">=" then L[1]*x + L[2]*y >= L[4] else L[1]*x + L[2]*y > L[4];
Q41L: [["A furniture workshop in Thika makes \\(x\\) sofas and \\(y\\) armchairs a week. Carpentry (in hours): each of the sofas needs \\(3\\) and each of the armchairs needs \\(7\\); \\(66\\) are available. Upholstery (in hours): each of the sofas needs \\(9\\) and each of the armchairs needs \\(2\\); \\(65\\) are available. The profit is Ksh \\(9000\\) on each of the sofas and Ksh \\(8000\\) on each of the armchairs.",[3,7,"<=",66],[9,2,"<=",65],9000,8000,[5,7],101000,false,[6,7],107000,"3 \\times 6 + 7 \\times 7 = 67 \\gt 66",[-1,-1],"sofas","armchairs","carpentry","upholstery","(\\frac{17}{3}, 7)",["hours of carpentry","hours of upholstery"],[3,9],[7,2]],
["A farmer in Narok buys \\(x\\) goats and \\(y\\) sheep to fatten for market. Grazing land (in acres): each of the goats needs \\(4\\) and each of the sheep needs \\(9\\); \\(78\\) are available. Money for vaccines (in hundred shillings): each of the goats needs \\(7\\) and each of the sheep needs \\(5\\); \\(72\\) are available. The profit is Ksh \\(9000\\) on each of the goats and Ksh \\(7000\\) on each of the sheep.",[4,9,"<=",78],[7,5,"<=",72],9000,7000,[6,6],96000,true,[7,6],648000/7,"4 \\times 7 + 9 \\times 6 = 82 \\gt 78",[-1,-1],"goats","sheep","grazing land","money for vaccines","(6, 6)",["acres of grazing land","hundred shillings of money for vaccines"],[4,7],[9,5]],
["A beadwork artist in Kajiado makes \\(x\\) pairs of earrings and \\(y\\) bracelets a week. Beads (in hundreds): each of the pairs of earrings needs \\(1\\) and each of the bracelets needs \\(9\\); \\(77\\) are available. Time (in hours): each of the pairs of earrings needs \\(9\\) and each of the bracelets needs \\(1\\); \\(69\\) are available. The profit is Ksh \\(400\\) on each of the pairs of earrings and Ksh \\(500\\) on each of the bracelets.",[1,9,"<=",77],[9,1,"<=",69],400,500,[5,8],6000,false,[7,8],6620,"1 \\times 7 + 9 \\times 8 = 79 \\gt 77",[6,7],"pairs of earrings","bracelets","beads","time","(6.8, 7.8)",["hundreds of beads","hours of time"],[1,1],[9,9]],
["A garage in Kakamega repairs \\(x\\) bicycles and \\(y\\) motorbikes a week. Mechanic time (in hours): each of the bicycles repaired needs \\(3\\) and each of the motorbikes repaired needs \\(7\\); \\(79\\) are available. Spare parts budget (in thousand shillings): each of the bicycles repaired needs \\(9\\) and each of the motorbikes repaired needs \\(1\\); \\(52\\) are available. The profit is Ksh \\(700\\) on each of the bicycles repaired and Ksh \\(500\\) on each of the motorbikes repaired.",[3,7,"<=",79],[9,1,"<=",52],700,500,[4,9],7300,false,[5,9],7950,"9 \\times 5 + 1 \\times 9 = 54 \\gt 52",[-1,-1],"bicycles repaired","motorbikes repaired","mechanic time","spare parts budget","(4.75, 9.25)",["hours of mechanic time","thousand shillings of spare parts budget"],[3,9],[7,1]],
["A mattress maker in Nakuru makes \\(x\\) mattresses and \\(y\\) pillows a day. Foam (in units): each of the mattresses needs \\(3\\) and each of the pillows needs \\(8\\); \\(42\\) are available. Sewing time (in hours): each of the mattresses needs \\(8\\) and each of the pillows needs \\(3\\); \\(57\\) are available. The profit is Ksh \\(900\\) on each of the mattresses and Ksh \\(500\\) on each of the pillows.",[3,8,"<=",42],[8,3,"<=",57],900,500,[6,3],6900,true,[7,3],12825/2,"3 \\times 7 + 8 \\times 3 = 45 \\gt 42",[-1,-1],"mattresses","pillows","foam","sewing time","(6, 3)",["units of foam","hours of sewing time"],[3,3],[8,8]],
["A solar shop in Garissa assembles \\(x\\) solar lamps and \\(y\\) phone chargers a week. Assembly time (in hours): each of the solar lamps needs \\(3\\) and each of the phone chargers needs \\(8\\); \\(52\\) are available. Testing time (in hours): each of the solar lamps needs \\(7\\) and each of the phone chargers needs \\(2\\); \\(68\\) are available. The profit is Ksh \\(900\\) on each of the solar lamps and Ksh \\(700\\) on each of the phone chargers.",[3,8,"<=",52],[7,2,"<=",68],900,700,[9,2],9500,false,[9,3],10160,"7 \\times 9 + 2 \\times 3 = 69 \\gt 68",[8,3],"solar lamps","phone chargers","assembly time","testing time","(8.8, 3.2)",["hours of assembly time","hours of testing time"],[3,7],[8,2]],
["A youth group in Kibera makes \\(x\\) bags of charcoal briquettes and \\(y\\) bags of cooking pellets a week. Sawdust (in kg): each of the bags of charcoal briquettes needs \\(2\\) and each of the bags of cooking pellets needs \\(7\\); \\(72\\) are available. Drying space (in square metres): each of the bags of charcoal briquettes needs \\(8\\) and each of the bags of cooking pellets needs \\(1\\); \\(72\\) are available. The profit is Ksh \\(80\\) on each of the bags of charcoal briquettes and Ksh \\(90\\) on each of the bags of cooking pellets.",[2,7,"<=",72],[8,1,"<=",72],80,90,[8,8],1360,true,[9,8],720,"2 \\times 9 + 7 \\times 8 = 74 \\gt 72",[-1,-1],"bags of charcoal briquettes","bags of cooking pellets","sawdust","drying space","(8, 8)",["kg of sawdust","square metres of drying space"],[2,8],[7,1]],
["A carpenter in Nyeri makes \\(x\\) school desks and \\(y\\) lockers a week. Timber (in planks): each of the school desks needs \\(3\\) and each of the lockers needs \\(7\\); \\(66\\) are available. Painting time (in hours): each of the school desks needs \\(9\\) and each of the lockers needs \\(1\\); \\(42\\) are available. The profit is Ksh \\(700\\) on each of the school desks and Ksh \\(200\\) on each of the lockers.",[3,7,"<=",66],[9,1,"<=",42],700,200,[4,6],4000,false,[4,8],4220,"3 \\times 4 + 7 \\times 8 = 68 \\gt 66",[3,7],"school desks","lockers","timber","painting time","(3.8, 7.8)",["planks of timber","hours of painting time"],[3,9],[7,1]],
["A dairy cooperative in Ol Kalou packs \\(x\\) crates of milk and \\(y\\) crates of yoghurt a day. Milk (in hundred litres): each of the crates of milk needs \\(1\\) and each of the crates of yoghurt needs \\(7\\); \\(32\\) are available. Cooling space (in units): each of the crates of milk needs \\(4\\) and each of the crates of yoghurt needs \\(7\\); \\(51\\) are available. The profit is Ksh \\(200\\) on each of the crates of milk and Ksh \\(500\\) on each of the crates of yoghurt.",[1,7,"<=",32],[4,7,"<=",51],200,500,[7,3],2900,false,[6,4],3100,"1 \\times 6 + 7 \\times 4 = 34 \\gt 32",[6,3],"crates of milk","crates of yoghurt","milk","cooling space","(\\frac{19}{3}, \\frac{11}{3})",["hundred litres of milk","units of cooling space"],[1,4],[7,7]],
["A leather worker in Kisumu makes \\(x\\) pairs of sandals and \\(y\\) leather belts a week. Leather (in cut pieces): each of the pairs of sandals needs \\(4\\) and each of the leather belts needs \\(7\\); \\(62\\) are available. Stitching time (in hours): each of the pairs of sandals needs \\(7\\) and each of the leather belts needs \\(1\\); \\(41\\) are available. The profit is Ksh \\(50\\) on each of the pairs of sandals and Ksh \\(60\\) on each of the leather belts.",[4,7,"<=",62],[7,1,"<=",41],50,60,[5,6],610,true,[6,6],2050/7,"4 \\times 6 + 7 \\times 6 = 66 \\gt 62",[-1,-1],"pairs of sandals","leather belts","leather","stitching time","(5, 6)",["cut pieces of leather","hours of stitching time"],[4,1],[7,7]]];
ix: 1+rand(10);
E: Q41L[ix];
a1: E[2][1]; b1: E[2][2]; c1: E[2][4]; a2: E[3][1]; b2: E[3][2]; c2: E[3][4];
pp: E[4]; pq: E[5]; bst: E[6]; t: E[7]; isint: E[8]; trp: E[9]; tv2: E[10]; brkd: E[11]; fl: E[12]; i1: E[13]; i2: E[14]; rw1: E[15]; rw2: E[16]; vd: E[17]; un: E[18];
ta1: a1*x+b1*y<=c1; ta2: a2*x+b2*y<=c2;
/* mixed conditions: a column of the two sentences (another mix where that column equals a row) */
col1: E[19][1]*x+E[19][2]*y<=c1; col2: E[20][1]*x+E[20][2]*y<=c2;
sw1: b1*x+a1*y<=c1; sw2: b2*x+a2*y<=c2;
dr1: a1*x+b1*y>=c1; dr2: a2*x+b2*y>=c2;
Pof(u, w) := pp*u + pq*w;
ptrp: Pof(trp[1], trp[2]);
validate_int(ex) := if integerp(ev(ex, simp)) then "" else "Type whole numbers.";
g3(v) := block([q,r], if v < 1000 then string(v) else (q: floor(v/1000), r: v - 1000*q, sconcat(g3(q), "\\,", if r < 10 then "00" elseif r < 100 then "0" else "", string(r))));
thou(v) := if abs(v) < 10000 then string(v) else g3(v);
